/**
 * Site search — lazily loaded index.
 *
 * The index is a static JSON file (static/search-index.json, generated by
 * scripts/build-search-index.mjs) fetched the first time a reader opens search
 * and cached for the session. Previously the same data was inlined into a
 * shared JS chunk that loaded on every page view, so every reader paid for a
 * feature most never use, and the cost grew with every post published.
 *
 * `ready` is exposed so the UI can say "loading…" rather than "no results" in
 * the fraction of a second before the fetch resolves — reporting an empty index
 * as an empty result set would be a lie.
 */
export const searchIndex = $state({
	entries: [],
	ready: false,
	failed: false
});

let inFlight = null;

/** Fetch the index once. Safe to call on every open; later calls are no-ops. */
export async function loadIndex() {
	if (searchIndex.ready || inFlight) return inFlight;

	inFlight = (async () => {
		try {
			const response = await fetch('/search-index.json');
			if (!response.ok) throw new Error(`HTTP ${response.status}`);
			searchIndex.entries = await response.json();
			searchIndex.ready = true;
		} catch {
			// Search failing should never break the page it sits in; the UI
			// reports it and everything else keeps working.
			searchIndex.failed = true;
		} finally {
			inFlight = null;
		}
	})();

	return inFlight;
}

/**
 * Search the loaded index. Every query token must match somewhere in a post
 * for it to count (AND semantics), and matches are weighted by where they
 * occur: title > tags > topic > description > body. Returns the top 8.
 */
export function search(query) {
	const trimmed = query.trim().toLowerCase();
	if (trimmed.length < 2) return []; // single characters match everything — noise
	if (!searchIndex.ready) return [];

	const tokens = trimmed.split(/\s+/);

	return searchIndex.entries
		.map((entry) => {
			let score = 0;
			for (const token of tokens) {
				let tokenScore = 0;
				if (entry._title.includes(token)) tokenScore += 5;
				if (entry._tags.some((tag) => tag.includes(token))) tokenScore += 4;
				if (entry._theme.includes(token)) tokenScore += 3;
				if (entry._description.includes(token)) tokenScore += 2;
				if (entry._body.includes(token)) tokenScore += 1;
				if (tokenScore === 0) return null; // token matched nowhere -> drop post
			}
			return { entry, score };
		})
		.filter(Boolean)
		.sort((a, b) => b.score - a.score)
		.slice(0, 8)
		.map(({ entry }) => entry);
}
